function canonicalName(name,group=''){let n=String(name||'').trim().toUpperCase().replace(/\s*\((?:IDEXX|CATALYST|PROCYTE|VETSCAN|ZOETIS|VCHECK|V200)[^)]*\)\s*$/i,'').replace(/\s*[-_/]\s*(?:IDEXX|CATALYST|PROCYTE|VETSCAN|ZOETIS|VCHECK).*$/i,'').trim();const urine=/요검사|urine|urinalysis/i.test(group)||/\(\s*(?:URINE|U)\s*\)|^URINE\s+/i.test(n)||['SPECIFIC GRAVITY','UPRO','UCRE'].includes(n);if(urine){n=n.replace(/\s*\(\s*(?:URINE|U)\s*\)/g,'').replace(/^URINE\s+/,'').trim();return urineAliases[n]||n;}return ({TRIG:'TG',LIPA:'LIP',FRU:'FRUCTOSAMINE',TT4:'TOTAL T4','ALB/GL':'A/G','BUN/CR':'BUN/CREA','NA/K':'NA/K'})[n]||aliases[n]||n;}
function normalizedLab(raw){const name=canonicalName(raw.name,raw.group);return {...raw,name,originalName:raw.originalName||raw.name,group:labGroup({...raw,name})};}
function sameLab(a,b,date){return labTab(a)===labTab(b)&&canonicalName(a.name,a.group)===canonicalName(b.name,b.group)&&(a.date||date)===(b.date||date)&&String(a.source||'').trim().toUpperCase()===String(b.source||'').trim().toUpperCase()&&String(a.unit||'').trim().toLowerCase()===String(b.unit||'').trim().toLowerCase();}
function mergeLabs(existing,incoming,mode,date){const out=copy(existing);for(const raw of incoming){if(!String(raw.value??'').trim())continue;const r=row({...normalizedLab(raw),date,confirmed:true});const matches=out.map((v,i)=>sameLab(v,r,date)?i:-1).filter(i=>i>=0);if(mode==='append'||matches.length!==1){out.push(r);continue;}const i=matches[0];if(mode==='replace')out[i]={...r,id:out[i].id};else if(!String(out[i].value??'').trim())out[i]={...r,id:out[i].id};}return out;}
function needsReview(r){return !!String(r.value??'').trim()&&!r.confirmed;}
function visibleLab(r,mode){return mode==='entered'?!!r.value:mode==='abnormal'?['높음','낮음'].includes(rangeStatus(r)):mode==='review'?needsReview(r):true;}
function patientDetail(d,p){const birth=d.patient?.birthDate||p.birthDate;let age='나이 미입력';if(birth&&birth<=d.date){const b=new Date(birth+'T00:00:00Z'),t=new Date(d.date+'T00:00:00Z');let months=(t.getUTCFullYear()-b.getUTCFullYear())*12+t.getUTCMonth()-b.getUTCMonth()-(t.getUTCDate()<b.getUTCDate()?1:0);if(Number.isFinite(months))age=months<12?Math.max(0,months)+'개월':Math.floor(months/12)+'세'+(months%12?' '+months%12+'개월':'');}const sex=d.patient?.sex||p.sex,n=d.patient?.neutered||p.neutered;return [age,d.patient?.breed||p.breed||'품종 미입력',sex==='male'||sex==='female'?(n==='yes'?'중성화 ':'')+(sex==='male'?'수컷':'암컷'):'성별 미입력',d.weight?d.weight+' kg':'체중 미입력'].join(' · ');}
