const templates={CBC:['WBC','NEU','LYM','MONO','EOS','BASO','RBC','HGB','HCT','MCV','MCH','MCHC','RDW','RETIC','PLT'],생화학:['GLU','BUN','CREA','SDMA','TP','ALB','GLOB','ALT','AST','ALP','GGT','TBIL','CHOL','TG','Ca','P','Na','K','Cl'],요검사:['요색','요잠혈','요빌리루빈','요유로빌리노겐','요케톤','요단백','요아질산염','요당','pH','USG','요백혈구 반응','UPC','요침사']};

const examChoices={skin:['특이 소견 없음','발적','가려움','탈모','피부 병변'],ears:['특이 소견 없음','분비물','발적','가려움'],eyes:['특이 소견 없음','충혈','분비물','혼탁'],oral:['특이 소견 없음','치석','치은염','치아 병변'],cardiac:['특이 소견 없음','심잡음','부정맥 의심'],respiratory:['특이 소견 없음','호흡음 이상','호흡 노력 증가'],abdomen:['특이 소견 없음','복부 통증','촉진 이상'],musculoskeletal:['특이 소견 없음','파행','통증'],neurologic:['특이 소견 없음','신경학적 이상']};
const labGroups=['CBC · 혈구검사','신장 관련','간·담도 관련','단백질','혈당','지질','전해질·무기질','췌장 관련','요검사','심장표지자','호르몬검사','감염성 검사','기타 혈액검사','기타 검사'];
const labMap=[templates.CBC,['BUN','CREA','CREATININE','SDMA'],['ALT','AST','ALP','ALKP','GGT','TBIL','TBILI','DBIL','BA'],['TP','ALB','ALBUMIN','GLOB','A/G','AGR'],['GLU','GLUCOSE','FRUCTOSAMINE'],['CHOL','CHOLESTEROL','TG','TRIG'],['CA','ICA','P','PHOS','NA','K','CL','MG','TCO2'],['AMYL','AMYLASE','LIP','LIPASE','CPL','FPL','PLI','TLI'],['USG','UPC','PH','요침사']];
function labGroup(r){if(labGroups.includes(r.group))return r.group;if(/요검사|urine|urinalysis/i.test(r.group))return '요검사';const n=canonicalName(r.name,r.group);if(templates.요검사.some(x=>x.toUpperCase()===n)||['요크레아티닌','요적혈구','요백혈구'].includes(n))return '요검사';if(['%NEU','%LYM','%MONO','%EOS','%BASO','%RETIC','MPV','PDW','PCT','P-LCR','TNCC','BAND'].includes(n))return 'CBC · 혈구검사';if(n==='BUN/CREA')return '신장 관련';if(n==='NA/K')return '전해질·무기질';if(/^(NT[- ]?PROBNP|PROBNP|CTNI|TROPONIN I)$/i.test(n))return '심장표지자';if(/^(TOTAL T4|FREE T4|T4|FT4|TSH)$/i.test(n)||/CORTISOL/.test(n))return '호르몬검사';if(/심장사상충|HEARTWORM|FELV|FIV/.test(n))return '감염성 검사';const idx=labMap.findIndex(a=>a.some(x=>x.toUpperCase()===n));return idx<0?(r.group==='blood'?'기타 혈액검사':'기타 검사'):labGroups[idx];}
