function blank(){return {date:today(),time:'',patient:{sex:'unknown',neutered:'unknown'},weight:null,veterinarian:'',history:'',medications:'',clinicalStatus:'inProgress',bcs:null,mcs:'',examSelection:['physical','nutrition'],exams:{},labs:[],images:[],overview:'',comparisonRecordId:'',summary:'',management:'',followup:'',questions:'',aiSource:'',reviewed:false};}
function row(v={}){return {id:uid(),group:'',name:'',originalName:'',value:'',unit:'',reference:'',source:'',date:'',confirmed:false,...v};}
function rangeStatus(r){const val=String(r.value??'').trim(),ref=String(r.reference??'').trim();if(!val)return '';if(!r.confirmed)return '대조 전';if(val==='판정 보류')return '판정 보류';if(/^(음성|양성|negative|positive|검출|불검출)$/i.test(val))return '정성 결과';const number='[-+]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)';if(!new RegExp('^'+number+'$').test(val))return '수치 비교 불가';const n=Number(val),m=ref.match(new RegExp('^\\s*('+number+')\\s*(?:~|–|—|-)\\s*('+number+')\\s*$'));if(m&&+m[1]<=+m[2])return n<+m[1]?'낮음':n>+m[2]?'높음':'범위 내';const one=ref.match(new RegExp('^\\s*(<=|>=|<|>|≤|≥)\\s*('+number+')\\s*$'));if(one){const op=one[1],v=+one[2],ok=op==='<'?n<v:op==='>'?n>v:op==='≤'||op==='<='?n<=v:n>=v;return ok?'범위 내':op.includes('<')||op==='≤'?'높음':'낮음';}return ref?'참고범위 형식 확인':'참고범위 미제공';}
