function printLabs(labs,previous=null){
 const labels={WBC:'백혈구',RBC:'적혈구',HGB:'혈색소',HCT:'적혈구 용적률',PLT:'혈소판',BUN:'요소질소',CREA:'크레아티닌',SDMA:'SDMA',ALT:'ALT',AST:'AST',ALP:'ALP',TP:'총단백',ALB:'알부민',GLOB:'글로불린',GLU:'혈당',CHOL:'콜레스테롤',TG:'중성지방',CA:'칼슘',P:'인',NA:'나트륨',K:'칼륨',CL:'염소',USG:'요비중',UPC:'요단백/크레아티닌 비율'};
 return groupedLabs(labs.filter(r=>String(r.value??'').trim())).map(g=>{
  const sources=[...new Set(g.rows.map(({r})=>r.source).filter(Boolean))],commonSource=sources.length===1&&g.rows.every(({r})=>r.source===sources[0]);
  return '<div class="lab-group"><h3>'+esc(g.group)+(commonSource?'<small class="group-source">'+esc(sources[0])+'</small>':'')+'</h3><table class="lab-table '+(previous?'with-prior':'')+'"><thead><tr><th>검사 항목</th><th class="numeric">이번 결과</th>'+(previous?'<th class="numeric">이전 결과<small>'+esc(previous.date)+'</small></th>':'')+'<th>단위</th><th>참고범위</th><th>참고범위 대비</th></tr></thead><tbody>'+g.rows.map(({r})=>{
   const c=previous?labComparison(r,previous,labs):null,label=labels[canonicalName(r.name,r.group)],state=rangeStatus(r);
   return '<tr><td>'+esc(r.name)+(label&&label!==r.name?'<small class="lab-name"> '+esc(label)+'</small>':'')+(!commonSource&&r.source?'<small>'+esc(r.source)+'</small>':'')+'</td><td class="numeric '+(outsideRange(r)?'lab-abnormal':'')+'">'+esc(r.value)+(outsideRange(r)?' '+(state==='높음'?'↑':'↓'):'')+'</td>'+(c?'<td class="numeric">'+esc(c.value)+(c.unit&&c.unit!==r.unit?' '+esc(c.unit):'')+'<small class="comparison-note '+(c.comparable?'is-comparable':'')+'">'+esc(c.note)+'</small>'+(!c.comparable&&c.source?'<small class="comparison-note">'+esc(c.source)+' · '+esc(c.reference||'참고범위 미제공')+'</small>':'')+'</td>':'')+'<td>'+esc(r.unit)+'</td><td>'+esc(r.reference||'미제공')+'</td><td class="'+(outsideRange(r)?'lab-abnormal':'')+'">'+esc(state)+'</td></tr>';
  }).join('')+'</tbody></table></div>';
 }).join('');
}
