 for(const [k,l] of Object.entries(exams))if(!imageStep(k)&&String(d.exams?.[k]||'').trim())findingRows.push([l,d.exams[k]]);
 if(findingRows.length){const brief=findingRows.filter(([,v])=>v.length<=180&&!v.includes('\n')),long=findingRows.filter(x=>!brief.includes(x));parts.push({title:'신체검사·진료 소견',keepTogether:!long.length&&brief.map(([,v])=>v).join('').length<600,body:(brief.length?'<div class="finding-table" role="table" aria-label="신체검사 소견">'+brief.map(([l,v])=>'<p class="finding-row" role="row"><strong role="rowheader">'+esc(l)+'</strong><span role="cell">'+esc(v)+'</span></p>').join('')+'</div>':'')+long.map(([l,v])=>note(l,v)).join('')});}
 for(const [key,title] of [['labs','혈액검사'],['urine','요검사'],['additional','추가 검사']]){const rows=(d.labs||[]).filter(r=>labTab(r)===key&&String(r.value??'').trim());const groups=key==='labs'?[{title:'혈액검사 · CBC',rows:rows.filter(r=>labGroup(r)==='CBC · 혈구검사')},{title:'혈액검사 · 생화학',rows:rows.filter(r=>labGroup(r)!=='CBC · 혈구검사')}]:[{title,rows}];for(const group of groups)if(group.rows.length)parts.push({title:group.title,body:'<p class="muted">참고범위는 검사기관 원본 기준입니다.'+(previous?' 이전 검사 '+esc(previous.date)+' · 비교 조건이 다르면 증감 판단을 보류합니다.':'')+'</p>'+printLabs(group.rows,previous)});}
