 async function openRecord(id){if(busy||dirty&&!g.confirm('작성 중인 입력을 버리고 다른 기록을 열까요?'))return;const n=++epoch;status('기록 불러오는 중…');try{const r=await request('/cases/'+encodeURIComponent(id)+'?view=healthcheck');if(!live(n))return;closeFile();item=r.item;d=copy(item.body.healthcheckChart);dirty=false;pending=null;proposal=null;undoAI=null;prior=null;priorList=[];priorNext='';saveMark=item.updated_at?new Date(item.updated_at).toLocaleTimeString('ko-KR'):'';imageCache.clear();photoSelection.clear();labSelection.clear();photoEditor='';historyOpen=false;screen='record';step='exams';error='';render();}catch(e){if(live(n))status('조회 실패 · '+e.message);}}
