 function bindLabTools(panel){updateLabTools(panel);panel.querySelectorAll('[data-lab-pick]').forEach(e=>e.onchange=()=>{const id=d.labs[+e.dataset.labPick].id;e.checked?labSelection.add(id):labSelection.delete(id);updateLabTools(panel);buttons();});panel.querySelector('[data-lab-filter]').onchange=e=>{labFilters[step]=e.target.value;render();};panel.querySelector('[data-first-review]').onclick=()=>{const i=d.labs.findIndex(r=>labTab(r)===step&&needsReview(r));if(i<0){status('확인 필요한 검사 결과가 없습니다.');return;}labFilters[step]='all';render();const el=root.querySelector('[data-row="'+i+'"]');el?.scrollIntoView({block:'center'});el?.querySelector('[data-lab=value]')?.focus();};panel.querySelector('[data-confirm-picked]').onclick=()=>{if(!edit()||busy)return;const selected=d.labs.map((r,i)=>labTab(r)===step&&labSelection.has(r.id)?i:-1).filter(i=>i>=0);if(!selected.length){status('원본과 대조한 검사를 선택해주세요.');return;}for(const i of selected)if(d.labs[i].name&&d.labs[i].value){d.labs[i].confirmed=true;labSelection.delete(d.labs[i].id);}changed();render();};panel.querySelector('[data-previous]').onclick=()=>void loadPriorList();if(prior||priorList.length||priorNext)showPrior(panel);}
