  const update=()=>{panel.querySelector('[data-bulk-actions]').hidden=!photoSelection.size;panel.querySelector('[data-photo-count]').textContent='선택 '+photoSelection.size+'장'+(photoSelection.size>shown.filter(({im})=>photoSelection.has(im.id)).length?' · 숨김 '+(photoSelection.size-shown.filter(({im})=>photoSelection.has(im.id)).length)+'장 포함':'');const all=panel.querySelector('[data-photo-all]'),n=shown.filter(({im})=>photoSelection.has(im.id)).length;all.checked=!!shown.length&&n===shown.length;all.indeterminate=n>0&&n<shown.length;buttons();};
